import type { TaskRecord } from './state/model.js'
import type { TaskState } from './types.js'

export const defaultPrunableWorktreeStates: TaskState[] = [
  'abandoned',
  'judge_pending',
  'judge_approved',
  'judge_adjusted',
  'judge_rejected',
]

export function isTaskWorktreePrunable(task: TaskRecord, allowedStates: ReadonlyArray<TaskState> = defaultPrunableWorktreeStates): boolean {
  return Boolean(task.worktreePath) && allowedStates.includes(task.state)
}

export function selectPrunableTaskWorktrees(tasks: TaskRecord[], allowedStates: ReadonlyArray<TaskState> = defaultPrunableWorktreeStates): TaskRecord[] {
  return tasks.filter((task) => isTaskWorktreePrunable(task, allowedStates))
}
